pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        c.initialize();

        vm.prank(address(this));
        c.transferOwnership(caller);

        vm.prank(caller);
        c.renounceOwnership();

        assertTrue(c.owner() == address(0));
    }
}
